        }

MEM = Memory()

def build_agent(sandbox):
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_agent_position()
    front, up, down = sandbox.get_whisker_readings()
    x, y = pos
    angle = agent_body.angle
    vx, vy = sandbox.get_agent_velocity()
    speed = math.hypot(vx, vy)

    state = MEM.data

    if state["phase"] == "APPROACH":
        # Adjust direction based on whiskers
        if front < 0.5:
            angle += 0.1  # Turn right
        elif up < 0.5:
            angle -= 0.1  # Turn down
        elif down < 0.5:
            angle += 0.1  # Turn up
        # Apply forward force
        fx = 50.0 * math.cos(angle)
        fy = 50.0 * math.sin(angle)
        sandbox.apply_agent_force(fx, fy)

        # Check if in activation zone
        if 5.0 <= x <= 10.0:
            state["phase"] = "UNLOCK"
            state["unlock_count"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply backward force
        fx = -50.0  # Ensures Fx < -34.0 N
        fy = 0.0
        sandbox.apply_agent_force(fx, fy)

        # Check unlock conditions
        if 5.0 <= x <= 10.0 and speed < 100.0 and fx < -34.0:
            state["unlock_count"] += 1
            if state["unlock_count"] >= 5:
                state["phase"] = "ESCAPE"
        else:
            state["unlock_count"] = 0
    elif state["phase"] == "ESCAPE":
        # Apply forward force to move to exit
        fx = 50.0 * math.cos(angle)
        fy = 50.0 * math.sin(angle)
        sandbox.apply_agent_force(fx, fy)

        # Check if in exit zone
        if x >= 15.0 and 0.5 <= y <= 2.5:
            state["phase"] = "HOLD"
