        # Check if still in exit zone
        if x >= 15.0 and 0.5 <= y <= 2.5:
            state["hold_count"] += 1
            if state["hold_count"] >= 5:
                # Task complete
                pass
        else:
            state["phase"] = "ESCAPE"

